package com.muxigame.city;
import java.util.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.npc.Villager;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsNpcDesigner {
 @GameTest(template="empty") public static void airMenuChoosesTwoBlocksAheadWithoutMovingPlayer(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();p.setPos(10.5,20,30.5);var before=p.position();for(float yaw:new float[]{0,90,180,-90}){p.setYRot(yaw);var at=CityNpcDesigner.airAnchor(p);h.assertTrue(at.equals(p.blockPosition().relative(p.getDirection(),2))&&at.distSqr(p.blockPosition())==4&&p.position().equals(before),"Default creation point stays two horizontal blocks ahead, not inside the player");}h.succeed();}
 static Villager actor(CityTestsCityWorks.Fixture f,UUID id){var a=EntityType.VILLAGER.create(f.test.getLevel());a.setUUID(id);a.setPos(f.bench.getX()+.5,f.bench.getY(),f.bench.getZ()+.5);return a;}
 static RuralSettlement.Site site(CityTestsCityWorks.Fixture f,String kind){var d=RuralSettlement.get(f.server);var site=new RuralSettlement.Site();site.city=f.city.id;site.pos=f.bench.asLong();site.kind=kind;site.expectedBlock="minecraft:crafting_table";d.state.sites.put(RuralSettlement.key(f.city.id,site.pos),site);return site;}
 @GameTest(template="empty") public static void templateItemKeepsOnlyAuthoringFields(GameTestHelper h){var wand=new ItemStack(Items.STICK);var custom=new CompoundTag();custom.putString("OtherMod","keep");wand.set(DataComponents.CUSTOM_DATA,CustomData.of(custom));var t=CityNpcDesigner.defaults(RuralRules.Role.HUNTER);t.name="猎户模板";t.huntRadius=96;CityNpcDesigner.store(wand,t);var saved=wand.get(DataComponents.CUSTOM_DATA).copyTag();var json=com.google.gson.JsonParser.parseString(saved.getString(CityNpcDesigner.KEY)).getAsJsonObject();h.assertTrue(saved.getString("OtherMod").equals("keep")&&CityNpcDesigner.read(wand).huntRadius==96,"Template persists on this item without overwriting unrelated components");h.assertTrue(json.keySet().equals(Set.of("schema","name","skin","role","female","start","end","nightStart","nightEnd","willingness","huntRadius")),"Whitelist excludes UUID, family, coins, stock, pregnancy, hunger, training and night decisions");h.succeed();}
 @GameTest(template="empty") public static void applyAndRepeatNeverCopyMoneyOrStocks(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var work=site(f,"farmer");var link=f.box();var box=d.state.boxes.get(RuralSettlement.key(f.city.id,f.chest.asLong()));box.linked=true;box.site=work.pos;box.stock.family=null;box.stock.wheat=4;long money=f.money();UUID id=UUID.randomUUID();var a=actor(f,id);var t=CityNpcDesigner.defaults(RuralRules.Role.FARMER);CityNpcDesigner.apply(f.server,f.city,a,t);var p=d.state.people.get(id);p.trainedHours=7;p.nourishment=17;int accounts=CityEconomy.get(f.server).state.accounts.size(),people=d.state.people.size();CityNpcDesigner.apply(f.server,f.city,a,t);h.assertTrue(f.money()==money&&CityEconomy.get(f.server).balance(CityEconomy.person(id))==0&&box.stock.wheat==4&&p.family.equals(box.stock.family)&&work.worker.equals(id),"New authoring binds one real site/storage, adds zero silver, keeps goods");h.assertTrue(accounts==CityEconomy.get(f.server).state.accounts.size()&&people==d.state.people.size()&&p.trainedHours==7&&p.nourishment==17,"Repeated application preserves identity, family, training, hunger and account");}h.succeed();}
 @GameTest(template="empty") public static void occupiedSiteFailsBeforeAnyEnrollment(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var work=site(f,"farmer");work.worker=f.worker;var d=RuralSettlement.get(f.server);String rural=CityEconomy.JSON.toJson(d.state),cash=CityEconomy.JSON.toJson(CityEconomy.get(f.server).state);var a=actor(f,UUID.randomUUID());boolean refused=false;try{CityNpcDesigner.apply(f.server,f.city,a,CityNpcDesigner.defaults(RuralRules.Role.FARMER));}catch(IllegalArgumentException ex){refused=true;}h.assertTrue(refused&&rural.equals(CityEconomy.JSON.toJson(d.state))&&cash.equals(CityEconomy.JSON.toJson(CityEconomy.get(f.server).state))&&!f.city.residents.contains(a.getUUID()),"Occupied job is rejected before membership, household, money or stock changes");}h.succeed();}
 @GameTest(template="empty") public static void templateCannotSilentlySwitchAnExistingBusiness(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){site(f,"farmer");var before=CityEconomy.JSON.toJson(RuralSettlement.get(f.server).state);boolean refused=false;try{CityNpcDesigner.apply(f.server,f.city,actor(f,f.worker),CityNpcDesigner.defaults(RuralRules.Role.FARMER));}catch(IllegalArgumentException ex){refused=true;}h.assertTrue(refused&&before.equals(CityEconomy.JSON.toJson(RuralSettlement.get(f.server).state)),"Career template does not steal an employed artisan or change existing economic ownership");}h.succeed();}
 @GameTest(template="empty") public static void artisanPresetReusesActualWorkshopWithoutFunding(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){long money=f.money();var t=CityNpcDesigner.defaults(RuralRules.Role.ARTISAN);t.name="维修甲";CityNpcDesigner.apply(f.server,f.city,actor(f,f.worker),t);h.assertTrue(f.person.role==RuralRules.Role.ARTISAN&&f.house.workers.contains(f.worker)&&f.money()==money&&WorkHours.config(f.server,f.worker).willingness==40,"Artisan preset uses the existing workshop employment/wage rules and does not grant funds");}h.succeed();}
 @GameTest(template="empty") public static void urbanFarmerGetsOneBusinessOnly(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var trade=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;town.urban=true;trade.state.towns.put(f.city.id,town);try{site(f,"farmer");var id=UUID.randomUUID();var a=actor(f,id);long money=f.money();var t=CityNpcDesigner.defaults(RuralRules.Role.FARMER);CityNpcDesigner.apply(f.server,f.city,a,t);CityNpcDesigner.apply(f.server,f.city,a,t);h.assertTrue(trade.state.businesses.values().stream().filter(b->id.equals(b.worker)&&b.kind.equals("urban_farmer")).count()==1&&f.money()==money,"Urban farm gets one functioning economic registration and no duplicate capital");}finally{trade.state.businesses.values().removeIf(b->f.city.id.equals(b.city));trade.state.towns.remove(f.city.id);}}h.succeed();}
 @GameTest(template="empty") public static void unpreparedCityCannotCreateABakerShell(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){site(f,"baker");var before=CityEconomy.JSON.toJson(RuralSettlement.get(f.server).state);boolean refused=false;try{CityNpcDesigner.apply(f.server,f.city,actor(f,UUID.randomUUID()),CityNpcDesigner.defaults(RuralRules.Role.BAKER));}catch(IllegalArgumentException ex){refused=true;}h.assertTrue(refused&&before.equals(CityEconomy.JSON.toJson(RuralSettlement.get(f.server).state)),"Missing finite economy is explicit; editor does not reset a town to make the NPC look functional");}h.succeed();}
 @GameTest(template="empty") public static void unknownOrInvalidTemplatesAreRejected(GameTestHelper h){var t=CityNpcDesigner.defaults(RuralRules.Role.HUNTER);t.huntRadius=257;boolean radius=false,skin=false,role=false;try{CityNpcDesigner.validate(t);}catch(IllegalArgumentException ex){radius=true;}t.huntRadius=128;t.skin="https://example.invalid/skin.png";try{CityNpcDesigner.validate(t);}catch(IllegalArgumentException ex){skin=true;}t.skin="";t.role=RuralRules.Role.VAGRANT;try{CityNpcDesigner.validate(t);}catch(IllegalArgumentException ex){role=true;}h.assertTrue(radius&&skin&&role,"Reject out-of-range patrol, external URL assets and unsupported career");h.succeed();}
}
